  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-104-1-03' AND q.question IS NOT DISTINCT FROM $swsi$老人福利法中，為了提高家庭照顧老人之意願及能力，提升老人在社區生活之自主性，政府 應自行或結合民間資源提供之社區式服務，不包含下列那一項？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$自立生活支持服務$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$教育服務$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$退休準備服務$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$餐飲服務4$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-104-1-03 目前文字與預期不同，停止'; END IF;
