  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-104-1-35' AND q.question IS NOT DISTINCT FROM $swsi$根據社會工作師公會全國聯合會訂定的社會工作倫理守則中，有關社會工作師應保守業務秘 密，但是有特殊情況時保密是需要受到限制。請問下列何者並非倫理守則中所規範的特殊情 況？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$案主死亡時$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$負有警告責任時$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$負有法律規定相關報告責任時$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$案主有致命危險的傳染疾病時7$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-104-1-35 目前文字與預期不同，停止'; END IF;
