  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-106-2-21' AND q.question IS NOT DISTINCT FROM $swsi$請問下列何者並非增強權能觀點社會工作取向的基本假設？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$承諾保護個人免於受剝削或壓迫$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$個人經驗深切且無力感，以致無法與環境交流實現自己$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$權能可以透過社會互動增加衍生更多的權能5$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$案主被視為有能力、有價值的個人$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-106-2-21 目前文字與預期不同，停止'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-106-2-35' AND q.question IS NOT DISTINCT FROM $swsi$下列有關從工業革命到慈善組織會社的歷史發展歷程，何者錯誤？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$在中世紀以前西方基督教社會裡，救濟貧民的工作主要由教會來承擔$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$1601 年伊莉莎白女王公布的濟貧法，為今日社會福利的直接源頭$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$1782 年通過「史賓漢蘭制」，鼓勵組成濟貧工會並恢復院外救濟方式$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$「史賓漢蘭制」也實施普及的食物量表，以家庭維持基本生計所需麵包價格為基準，來救濟貧民6$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$C$swsi$) THEN RAISE EXCEPTION 'SW-106-2-35 目前文字與預期不同，停止'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-107-2-11' AND q.question IS NOT DISTINCT FROM $swsi$社會工作發展中，價值觀不斷地轉變。請問下列有關社會工作價值觀取向之描述，何者比較正確？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$社會正義取向的價值觀認為資本主義的缺失和種族主義與其他形式的壓迫，產生受剝奪的低下階 層。因此，必須進行基本的社會改革4$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$臨床取向的價值觀著重於對實務工作者的保護$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$父權主義取向的價值觀認為應該依賴政府或民間的財源幫助案主過有德性、完整且豐富的生活$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$專業自我保衛取向的價值觀強調價值衝突與倫理兩難的議題$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-107-2-11 目前文字與預期不同，停止'; END IF;
