UPDATE public.questions SET major=$swsi$社會工作倫理$swsi$, topic=$swsi$保密原則 > 保密例外情況$swsi$, keywords=$swsi$保密, 業務秘密, 案主死亡, 警告責任, 法律報告, 致命傳染$swsi$, exp_why=$swsi$(A)『案主死亡時』不是倫理守則所列解除保密的特殊情況。$swsi$, exp_others=$swsi$(B)負有警告責任、(C)負有法律規定報告責任、(D)案主有致命危險的傳染疾病——皆為守則所列保密受限的特殊情況。$swsi$, exp_trap=$swsi$保密是『相對』非絕對；例外＝危害自己或他人生命、法律通報責任、法院命令、案主同意、個案研討/督導、致命傳染病、警告可預見第三人(Tarasoff)。$swsi$, exp_raw=$swsi$$swsi$, mnemonic=$swsi$保密是「相對」非絕對:例外＝危害自己或他人生命、法定通報、法院命令、案主同意、個案研討督導、致命傳染病、警告可預見第三人(Tarasoff)。$swsi$, extension=$swsi$社會工作倫理(保密原則)。$swsi$, law=$swsi$$swsi$, mistake=$swsi$概念混淆$swsi$, analysis_status=$swsi$ready$swsi$ WHERE id='SW-104-1-35';
UPDATE public.questions SET major=$swsi$心理健康$swsi$, topic=$swsi$醫務社工 > 4Rs評估法$swsi$, keywords=$swsi$4Rs, Role, Reaction, Recovery, Resource$swsi$, exp_why=$swsi$(C)錯誤：4Rs不含『症狀恢復狀況(Recovery)』；4Rs＝角色/反應/關係/資源。$swsi$, exp_others=$swsi$(A)社會角色Role、(B)情緒反應Reaction、(D)問題解決的資源Resources——皆為4Rs面向。$swsi$, exp_trap=$swsi$醫務社工社會診斷4Rs(Doremus 1976)：角色(Role)、反應(Reaction,情緒態度)、關係(Relationship)、資源(Resources)。$swsi$, exp_raw=$swsi$$swsi$, mnemonic=$swsi$醫務社工社會診斷4Rs(Doremus 1976):角色Role/反應Reaction(情緒態度)/關係Relationship/資源Resources。$swsi$, extension=$swsi$醫務社會工作(社會系統紀錄4Rs)。$swsi$, law=$swsi$$swsi$, mistake=$swsi$概念混淆$swsi$, analysis_status=$swsi$ready$swsi$ WHERE id='SW-105-2-12';
