  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='DS-108-2-38' AND q.question IS NOT DISTINCT FROM $swsi$2005 年之前，社工人力並未普遍於社區組織中被運用，其原因有那些？ ①「社區發展工作綱要」強調社區組織的「志工化」 ②社區組織無能力聘用專職人力 ③政府支持補助社工專職人力，但社區幹部不接受 ④社區場域派系糾葛抑制社工之專業能力發揮$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$①②③$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$②③④$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$①③④$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$①②④$swsi$ AND q.major IS NOT DISTINCT FROM NULL AND q.topic IS NOT DISTINCT FROM NULL AND q.keywords IS NOT DISTINCT FROM NULL AND q.exp_why IS NOT DISTINCT FROM NULL AND q.exp_others IS NOT DISTINCT FROM NULL AND q.exp_trap IS NOT DISTINCT FROM NULL AND q.exp_raw IS NOT DISTINCT FROM NULL AND q.mnemonic IS NOT DISTINCT FROM NULL AND q.extension IS NOT DISTINCT FROM NULL AND q.law IS NOT DISTINCT FROM NULL AND q.mistake IS NOT DISTINCT FROM NULL AND q.analysis_status IS NOT DISTINCT FROM $swsi$review$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$D$swsi$) THEN RAISE EXCEPTION 'DS-108-2-38 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='DS-109-2-26' AND q.question IS NOT DISTINCT FROM $swsi$有關焦點團體的實施特色，下列敘述何者正確？①焦點團體因為是針對特定主題的討論，成員間難免針鋒相對 ②是一種半結構式的團體模式 ③通常成員的人數較多，人數約在 25 人以上，以便充分蒐集資料讓討論內容有代表性 ④會充分討論一個問題後，才到下一個問題 ⑤會採用比較自由的方式，在所有題目間跳動發表意見，增加討論的流暢性$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$①②$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$③④$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$③⑤$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$②④$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$團體工作$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$團體類型 > 焦點團體特色$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$焦點團體, 半結構, 充分討論, 自由方式, 實施特色$swsi$ AND q.exp_why IS NOT DISTINCT FROM NULL AND q.exp_others IS NOT DISTINCT FROM NULL AND q.exp_trap IS NOT DISTINCT FROM NULL AND q.exp_raw IS NOT DISTINCT FROM NULL AND q.mnemonic IS NOT DISTINCT FROM NULL AND q.extension IS NOT DISTINCT FROM NULL AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$review$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$D$swsi$) THEN RAISE EXCEPTION 'DS-109-2-26 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SP108-2-09' AND q.question IS NOT DISTINCT FROM $swsi$對於聯合國在1979 年通過消除對婦女一切形式歧視公約(CEDAW)，並在1981 年正式生效，下列敘述何者錯誤？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$此公約被稱為婦女人權法典$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$我國是在2007 年經總統批准並頒發加入書$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$為明定CEDAW 具有國內法效力，我國在2010 年經行政院送出消除對婦女一切形式歧視公約施行法草案，經立法院2011 年三讀通過，並自2012 年1 月1 日起施行$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$依CEDAW 規定，每5 年提出我國消除對婦女歧視國家報告$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$婦女與性別法規$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$CEDAW施行法 > CEDAW國家報告$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$消除對婦女歧視公約, CEDAW, 婦女人權法典, 施行法, 國家報告$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(D)是錯的：CEDAW施行法的國家報告是『每4年』提出，不是每5年。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(A)CEDAW被稱為婦女人權法典、(B)我國2007年經總統批准並頒發加入書、(C)我國2010年送出施行法以明定國內法效力(施行法民國100年制定)——大致正確。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$CEDAW(1979通過/1981生效)＝婦女人權法典；國家報告每『4年』。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$CEDAW(1979通過/1981生效)＝婦女人權法典；施行法報告每4年。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$CEDAW(1979通過、1981生效)；消除對婦女歧視之實質平等與暫行特別措施。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$消除對婦女一切形式歧視公約施行法。$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$法規混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$D$swsi$) THEN RAISE EXCEPTION 'SP108-2-09 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-104-1-03' AND q.question IS NOT DISTINCT FROM $swsi$老人福利法中，為了提高家庭照顧老人之意願及能力，提升老人在社區生活之自主性，政府 應自行或結合民間資源提供之社區式服務，不包含下列那一項？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$自立生活支持服務$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$教育服務$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$退休準備服務$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$餐飲服務$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$老人服務$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$老人福利法 > 社區式服務範圍$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$老人福利法, 社區式服務, 自立生活, 退休準備, 教育服務$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(A)不屬老福法社區式服務：『自立生活支持服務』是身心障礙者權益保障法的服務，非老福法社區式服務。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(B)教育服務、(C)退休準備服務、(D)餐飲服務——皆為老福法社區式服務。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$自立生活支持＝身權法;老福法社區式＝教育/退休準備/餐飲等。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$老福法社區式服務＝保健/醫療/復健/餐飲/教育/退休準備等(非自立生活支持)。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$老人福利(社區式服務)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$老人福利法$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$法規混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-104-1-03 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-104-1-12' AND q.question IS NOT DISTINCT FROM $swsi$下列關於評估（evaluation）的敘述，何者錯誤？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$指對一種問題和需求評定的過程$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$過程性評估關心工作的過程及各階段的工作如何影響最後的結果$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$著重在於案主和工作者所共同設定的目標是否達成$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$為了有效運作評估系統，需要採用標準化的紀錄格式$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$工作技巧$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$評估與預估 > 評估特性$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$評估, evaluation, 目標達成, 過程性評估, 標準化紀錄$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(A)錯誤：『對問題和需求評定的過程』是『預估(assessment)』，不是『評估(evaluation)』。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(B)過程性評估關心各階段如何影響結果、(C)著重共同設定目標是否達成、(D)需採標準化紀錄格式——皆正確。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$預估(assessment)＝了解問題與需求、持續、案主與社工雙向的過程;評估(evaluation)＝檢視目標是否達成(含過程性與成果評估)。生態評量仍須運用專業知識架構。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$預估assessment＝了解問題與需求、持續、案主社工雙向;評估evaluation＝檢視目標是否達成(過程性+成果);診斷以預估為基礎。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$社會工作過程(評估evaluation)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-104-1-12 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-104-1-35' AND q.question IS NOT DISTINCT FROM $swsi$根據社會工作師公會全國聯合會訂定的社會工作倫理守則中，有關社會工作師應保守業務秘 密，但是有特殊情況時保密是需要受到限制。請問下列何者並非倫理守則中所規範的特殊情 況？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$案主死亡時$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$負有警告責任時$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$負有法律規定相關報告責任時$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$案主有致命危險的傳染疾病時$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$社會工作倫理$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$保密原則 > 保密例外情況$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$保密, 業務秘密, 案主死亡, 警告責任, 法律報告, 致命傳染$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(A)『案主死亡時』不是倫理守則所列解除保密的特殊情況。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(B)負有警告責任、(C)負有法律規定報告責任、(D)案主有致命危險的傳染疾病——皆為守則所列保密受限的特殊情況。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$保密是『相對』非絕對；例外＝危害自己或他人生命、法律通報責任、法院命令、案主同意、個案研討/督導、致命傳染病、警告可預見第三人(Tarasoff)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$保密是「相對」非絕對:例外＝危害自己或他人生命、法定通報、法院命令、案主同意、個案研討督導、致命傳染病、警告可預見第三人(Tarasoff)。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$社會工作倫理(保密原則)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-104-1-35 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-105-2-12' AND q.question IS NOT DISTINCT FROM $swsi$醫務社會工作的個案工作，在評估上主要是以心理暨社會評估取向，經常採用的方式有社會 系統紀錄法(4Rs)，下列何者錯誤?$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$Role（社會角色）$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$Reaction（情緒反應）$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$Recovery（症狀恢復情況）$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$Resource（問題解決的資源）$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$心理健康$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$醫務社工 > 4Rs評估法$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$4Rs, Role, Reaction, Recovery, Resource$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(C)錯誤：4Rs不含『症狀恢復狀況(Recovery)』；4Rs＝角色/反應/關係/資源。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(A)社會角色Role、(B)情緒反應Reaction、(D)問題解決的資源Resources——皆為4Rs面向。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$醫務社工社會診斷4Rs(Doremus 1976)：角色(Role)、反應(Reaction,情緒態度)、關係(Relationship)、資源(Resources)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$醫務社工社會診斷4Rs(Doremus 1976):角色Role/反應Reaction(情緒態度)/關係Relationship/資源Resources。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$醫務社會工作(社會系統紀錄4Rs)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$C$swsi$) THEN RAISE EXCEPTION 'SW-105-2-12 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-106-2-09' AND q.question IS NOT DISTINCT FROM $swsi$「工具性日常生活活動功能」量表（Instrumental Activities of Daily Living, IADLs）是用以評估老人獨立自主生活能力的評估工具，下列那一種功能不是評估項目之一？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$食物烹調$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$穿脫衣褲$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$使用電話$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$上街購物$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$老人服務$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$評估工具 > IADLs項目$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$IADLs, 工具性日常, 食物烹調, 穿脫衣褲, 購物$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$IADLs(工具性日常生活)評估上街購物、烹調、使用電話等「較複雜」活動;(B)「穿脫衣褲」屬基本日常生活(ADLs),不是IADLs。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(A)食物烹調、(C)使用電話、(D)上街購物——皆為IADLs項目。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$ADLs=吃飯穿衣洗澡等基本自理;IADLs=購物煮飯打電話理財等較複雜活動。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$IADLs:烹調/電話/購物(穿脫衣褲屬ADLs)。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$評估工具;IADLs項目。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$B$swsi$) THEN RAISE EXCEPTION 'SW-106-2-09 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-106-2-21' AND q.question IS NOT DISTINCT FROM $swsi$請問下列何者並非增強權能觀點社會工作取向的基本假設？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$承諾保護個人免於受剝削或壓迫$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$個人經驗深切且無力感，以致無法與環境交流實現自己$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$權能可以透過社會互動增加衍生更多的權能$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$案主被視為有能力、有價值的個人$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$處遇模式$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$增強權能 > 增強權能基本假設$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$增強權能, 保護免於剝削, 無力感, 權能互動, 案主能力$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(A)並非增權假設：增權強調案主『自己增能』，而非由社工『承諾保護』案主免於壓迫(那讓案主成被動受保護者)。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(B)無力感深切以致無法與環境交流、(C)權能可透過社會互動增加、(D)案主是有能力有價值的個人——皆為增權假設。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$增權＝案主自主增能(非社工保護案主)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$增強權能(empowerment)：Solomon(1976)源自美國少數民族增權；無力感來源＝對自己負向評價/與外在系統負向互動/鉅視環境阻礙；核心＝案主有能力有價值、問題源於無力感與環境壓迫(非個人缺陷)、社工與案主平等協同夥伴(非權威專家)、權能可透過社會互動增加。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$社會工作理論(增強權能基本假設)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-106-2-21 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-106-2-35' AND q.question IS NOT DISTINCT FROM $swsi$下列有關從工業革命到慈善組織會社的歷史發展歷程，何者錯誤？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$在中世紀以前西方基督教社會裡，救濟貧民的工作主要由教會來承擔$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$1601 年伊莉莎白女王公布的濟貧法，為今日社會福利的直接源頭$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$1782 年通過「史賓漢蘭制」，鼓勵組成濟貧工會並恢復院外救濟方式$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$「史賓漢蘭制」也實施普及的食物量表，以家庭維持基本生計所需麵包價格為基準，來救濟貧民$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$社會工作專業$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$歷史發展 > 濟貧法歷史$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$濟貧法, 史賓漢蘭制, 伊莉莎白, 教會救濟, 食物量表$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(C)錯誤：『史賓漢蘭制』是1795年(非1782)；1782年是吉爾伯特法(Gilbert Act)。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(A)中世紀前救濟由教會承擔、(B)1601伊莉莎白濟貧法為社福直接源頭、(D)史賓漢蘭制以麵包價格為基準的食物量表——皆正確。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$1782吉爾伯特法;1795史賓漢蘭制(別搞混年代)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$英國社工史：1601伊莉莎白濟貧法(現代社福源頭,稅收/教區辦救濟、區分有無工作能力、親屬責任、兼採院內外)→1782吉爾伯特法(院外救濟)→1795史賓漢蘭制(麵包量表院外補貼)→1834新濟貧法(全國統一、劣等處遇、院內為原則,較舊法嚴格)。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$社會工作史(濟貧法歷史)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$C$swsi$) THEN RAISE EXCEPTION 'SW-106-2-35 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-107-2-11' AND q.question IS NOT DISTINCT FROM $swsi$社會工作發展中，價值觀不斷地轉變。請問下列有關社會工作價值觀取向之描述，何者比較正確？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$社會正義取向的價值觀認為資本主義的缺失和種族主義與其他形式的壓迫，產生受剝奪的低下階 層。因此，必須進行基本的社會改革$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$臨床取向的價值觀著重於對實務工作者的保護$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$父權主義取向的價值觀認為應該依賴政府或民間的財源幫助案主過有德性、完整且豐富的生活$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$專業自我保衛取向的價值觀強調價值衝突與倫理兩難的議題$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$社會工作專業$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$專業價值 > 社工價值取向$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$社會正義, 臨床取向, 父權主義, 專業自我保衛, 價值取向$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(A)正確：社會正義取向認為資本主義缺失與種族主義等壓迫造成受剝奪的低下階層，故須進行基本的社會改革。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(B)『保護實務工作者』是防衛取向(非臨床)；(C)父權主義是要案主『不依賴』、過有德生活(非依賴財源)；(D)『價值衝突與倫理兩難』是臨床取向(非專業自我保衛)。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$Reamer六種價值取向：父權主義(讓案主過有德性生活、不依賴)、社會正義(對抗壓迫與結構改革)、宗教、臨床(聚焦倫理兩難)、防衛/專業自我保衛(保護實務工作者)、無道德(純技術不涉價值)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$Reamer六價值取向:父權主義/社會正義/宗教/臨床(聚焦倫理兩難)/防衛(專業自我保衛)/無道德(純技術不涉價值)。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$社會工作價值(價值取向)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$A$swsi$) THEN RAISE EXCEPTION 'SW-107-2-11 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-107-2-21' AND q.question IS NOT DISTINCT FROM $swsi$社會工作可分為七大階段，請問尋求澄清、反應內容與感受是屬於那一階段主要使用的技巧？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$開始期$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$探索期$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$執行和評估期$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$結束期$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$工作技巧$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$工作階段 > 探索期技巧$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$探索期, 澄清, 反應內容, 反應感受, 開始期$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$尋求澄清、反應內容與感受——屬探索期主要使用的技巧;(B)。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(A)開始期重建立關係、(C)執行和評估期重處遇、(D)結束期重收尾——皆非「澄清與反應」的探索技巧。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$探索期要「聽懂並回應」案主:澄清、反映內容與感受以深入了解。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$探索期技巧=澄清+反應內容與感受。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$工作階段;探索期技巧。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$B$swsi$) THEN RAISE EXCEPTION 'SW-107-2-21 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='SW-107-2-35' AND q.question IS NOT DISTINCT FROM $swsi$下列有關「家庭暴力防治法」中保護令規定的敘述，何者錯誤？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$保護令可分為暫時保護令、緊急保護令及通常保護令$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$法官為保護被害人，得於通常保護令審理終結前，依聲請或職權核發暫時保護令$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$通常保護令有效期間為兩年以下，得依需要聲請延長$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$法院若認為被害人有受家庭暴力之急迫危險者，應於 24 小時內以書面核發緊急保護令$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$性別與婦女服務$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$家庭暴力防治法 > 保護令核發時限$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$家暴法, 緊急保護令, 24小時, 通常保護令, 暫時保護令$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$(D)錯誤：法院認被害人有受家暴之急迫危險者，應於『4小時內』以書面核發緊急保護令(非24小時)。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$(A)保護令分暫時/緊急/通常、(B)通常保護令審理終結前得依聲請或職權核發暫時保護令、(C)通常保護令2年以下得延長——皆正確。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$緊急保護令＝法院4小時內核發(24小時是責任通報時限)。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM $swsi$$swsi$ AND q.mnemonic IS NOT DISTINCT FROM $swsi$家庭暴力防治法(1998公布)：§3家庭成員含配偶/前配偶、現有或曾有同居/家長家屬關係、直系血親姻親、四親等內旁系血親姻親;民事保護令三種＝通常(2年以下得延長)/暫時/緊急(法院4小時內核發);責任通報24小時。$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$家庭暴力防治法(保護令)。$swsi$ AND q.law IS NOT DISTINCT FROM $swsi$家庭暴力防治法（緊急保護令應於4小時內核發，非24小時）$swsi$ AND q.mistake IS NOT DISTINCT FROM $swsi$法規混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$D$swsi$) THEN RAISE EXCEPTION 'SW-107-2-35 修正後內容不符，取消'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.id='HBSE-115-2-026' AND q.question IS NOT DISTINCT FROM $swsi$針對老年期的發展，有關死亡與臨終的因應模式，下列敘述何者錯誤？$swsi$ AND q.opt_a IS NOT DISTINCT FROM $swsi$恐懼管理理論認為人們會啟動近端與遠端防衛機轉來減少死亡焦慮，例如否認自己會過早死 亡，或透過健康飲食、運動來增加對健康的控制感$swsi$ AND q.opt_b IS NOT DISTINCT FROM $swsi$生命回顧療法（life review therapy）透過回顧與反思，協助處理生命中尚未解決的衝突或議題$swsi$ AND q.opt_c IS NOT DISTINCT FROM $swsi$社會工作者應儘量避免談論死亡，以免增加長輩對死亡與臨終的焦慮，甚至引發憂鬱$swsi$ AND q.opt_d IS NOT DISTINCT FROM $swsi$透過敘事治療（narrative therapy）為失落與死亡重建意義，促進正向自我認同，有助於人們為 臨終做好準備$swsi$ AND q.major IS NOT DISTINCT FROM $swsi$各年齡發展$swsi$ AND q.topic IS NOT DISTINCT FROM $swsi$老年期發展 > 死亡與臨終因應$swsi$ AND q.keywords IS NOT DISTINCT FROM $swsi$死亡焦慮,生命回顧,敘事治療,防衛機轉,社會工作介入$swsi$ AND q.exp_why IS NOT DISTINCT FROM $swsi$選項 C 認為社會工作者應避免談論死亡，與老年期臨終關懷的核心原則相左。專業介入強調開放且支持性地討論死亡議題，以協助長者處理未竟事宜、減少孤立感並促進心理適應，迴避反而可能阻礙情緒表達與意義重建，故此敘述錯誤，為本題正解。$swsi$ AND q.exp_others IS NOT DISTINCT FROM $swsi$選項 A 正確說明恐懼管理理論中個體透過近端與遠端防衛機轉降低死亡焦慮；選項 B 正確指出生命回顧療法透過回顧與反思協助處理未解決的衝突或議題；選項 D 正確說明敘事治療可為失落與死亡重建意義，促進正向自我認同。$swsi$ AND q.exp_trap IS NOT DISTINCT FROM $swsi$考生易以為「避免談論死亡」是保護長者的善意舉措，卻忽略了在專業社會工作與心理學觀點中，適時的死亡對話是促進心理適應與安寧照護的重要環節，迴避並非正確介入策略。$swsi$ AND q.exp_raw IS NOT DISTINCT FROM NULL AND q.mnemonic IS NOT DISTINCT FROM $swsi$談死非禁忌，對話助安寧$swsi$ AND q.extension IS NOT DISTINCT FROM $swsi$生命回顧療法與敘事治療在老年心理介入中的應用比較$swsi$ AND q.law IS NOT DISTINCT FROM NULL AND q.mistake IS NOT DISTINCT FROM $swsi$概念混淆$swsi$ AND q.analysis_status IS NOT DISTINCT FROM $swsi$ready$swsi$ AND q.answer IS NOT DISTINCT FROM $swsi$C$swsi$) THEN RAISE EXCEPTION 'HBSE-115-2-026 修正後內容不符，取消'; END IF;
  IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN ('DS-108-2-38', 'DS-109-2-26', 'SP108-2-09', 'SW-104-1-03', 'SW-104-1-12', 'SW-104-1-35', 'SW-105-2-12', 'SW-106-2-09', 'SW-106-2-21', 'SW-106-2-35', 'SW-107-2-11', 'SW-107-2-21', 'SW-107-2-35', 'HBSE-115-2-026') AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION '有其他題目被改到，取消'; END IF;
  IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN ('DS-108-2-38', 'DS-109-2-26', 'SP108-2-09', 'SW-104-1-03', 'SW-104-1-12', 'SW-104-1-35', 'SW-105-2-12', 'SW-106-2-09', 'SW-106-2-21', 'SW-106-2-35', 'SW-107-2-11', 'SW-107-2-21', 'SW-107-2-35', 'HBSE-115-2-026') AND ((b.row->'answer') IS DISTINCT FROM (to_jsonb(q)->'answer') OR (b.row->'accepted_answers') IS DISTINCT FROM (to_jsonb(q)->'accepted_answers') OR (b.row->'grading_mode') IS DISTINCT FROM (to_jsonb(q)->'grading_mode'))) THEN RAISE EXCEPTION '答案或給分被改到，取消'; END IF;
END $assert$;
SELECT id, answer, analysis_status, left(coalesce(exp_why,''),20) AS exp_why_head FROM public.questions WHERE id IN ('DS-108-2-38', 'DS-109-2-26', 'SP108-2-09', 'SW-104-1-03', 'SW-104-1-12', 'SW-104-1-35', 'SW-105-2-12', 'SW-106-2-09', 'SW-106-2-21', 'SW-106-2-35', 'SW-107-2-11', 'SW-107-2-21', 'SW-107-2-35', 'HBSE-115-2-026') ORDER BY id;
COMMIT;
